import { sim, knob } from './sim-core.js'

const excess = (used, limit) => Math.max(0, used - limit)
const percentage = (part, total) => 100 * part / total
const triangular = n => n * (n + 1) / 2
const sigmoid = x => 1 / (1 + Math.exp(-x))

